import ctypes
from functools import wraps
from pathlib import Path
import sys
sys.path.insert(0,str(Path.cwd()/'tests'))
import benchmark_excavator_cuda_mcts as benchmark
from stacking_common.search.mcts.search import MonteCarloTreeSearch
cudart=ctypes.CDLL('/usr/local/cuda-13.0/targets/x86_64-linux/lib/libcudart.so')
original=MonteCarloTreeSearch.search
@wraps(original)
def captured(self,*args,**kwargs):
 status=cudart.cudaProfilerStart()
 if status: raise RuntimeError(f'cudaProfilerStart failed: {status}')
 try:
  return original(self,*args,**kwargs)
 finally:
  status=cudart.cudaProfilerStop()
  if status: raise RuntimeError(f'cudaProfilerStop failed: {status}')
MonteCarloTreeSearch.search=captured
benchmark.main()
